"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface GitCommitHorizontalIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface GitCommitHorizontalIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const GitCommitHorizontalIcon = forwardRef<
 GitCommitHorizontalIconHandle,
 GitCommitHorizontalIconProps
>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const lineVariants = (from: "start" | "end"): Variants => ({
   normal: { strokeDashoffset: 0, opacity: 1 },
   animate: {
    strokeDashoffset: from === "start" ? [7, 0] : [-7, 0],
    opacity: [0, 1],
    transition: {
     strokeDashoffset: { duration: 0.4 * duration, ease: "easeOut" },
     opacity: { duration: 0.25 * duration, ease: "easeOut" },
    },
   },
  });

  const commitVariants: Variants = {
   normal: { scale: 1 },
   animate: {
    scale: [1, 1.35, 0.92, 1],
    transition: {
     duration: 0.5 * duration,
     ease: "easeInOut",
     times: [0, 0.4, 0.75, 1],
     delay: 0.3 * duration,
    },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.line
       x1="3"
       x2="9"
       y1="12"
       y2="12"
       strokeDasharray="7"
       strokeDashoffset="0"
       variants={lineVariants("end")}
      />
      <m.circle
       cx="12"
       cy="12"
       r="3"
       variants={commitVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "12px" }}
      />
      <m.line
       x1="15"
       x2="21"
       y1="12"
       y2="12"
       strokeDasharray="7"
       strokeDashoffset="0"
       variants={lineVariants("start")}
      />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

GitCommitHorizontalIcon.displayName = "GitCommitHorizontalIcon";
export { GitCommitHorizontalIcon };
